  const pick=pickCelestial();
  if(pick&&pick.kind==='body'){ setSkyTempleFocus({kind:'body',body:_templeBodyFromPick(pick),pick:pick}); return true; }
  if(pick&&pick.kind==='sign'){ setSkyTempleFocus({kind:'sign',pick:pick}); return true; }
